import os
import sys
import subprocess
import time
from collections import deque

def read_token():
    try:
        with open('token.txt', 'r') as f:
            return f.read().strip()
    except (IOError, OSError):
        return None

def check_auth():
    token = os.getenv('RUNNER_TOKEN')
    if not token:
        return False
    expected_token = read_token()
    if not expected_token:
        return False
    return token.strip() == expected_token.strip()

def execute_command(cmd, output_queue):
    try:
        result = subprocess.run(cmd, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        output_queue.append(result.stdout)
    except subprocess.CalledProcessError as e:
        output_queue.append(f"Command failed: {e.stderr.strip()}")
    except Exception as e:
        output_queue.append(f"Error executing command: {str(e)}")

def main():
    if not check_auth():
        print("access denied", file=sys.stderr)
        sys.exit(1)

    command_queue = deque(maxlen=3)
    command_window = deque(maxlen=10)
    last_start_time = time.time()

    while True:
        try:
            cmd = sys.stdin.readline().strip()
            if not cmd:
                break

            if len(command_queue) >= 3:
                continue

            start_time = time.time()
            command_window.append((start_time, cmd))

            if len(command_window) > 10:
                oldest_start = command_window.popleft()[0]
                if start_time - oldest_start < 1:
                    continue

            command_queue.append(cmd)
            execute_command(cmd, output_queue=sys.stdout)

            # Update last start time for rate limiting
            last_start_time = time.time()

        except KeyboardInterrupt:
            break
        except Exception as e:
            print(f"Unexpected error: {e}", file=sys.stderr)
            sys.exit(1)

if __name__ == "__main__":
    output_queue = []
    main()

import os
import sys
import time
from threading import Thread, Lock
from queue import Queue

def verify_auth():
    token_env = os.getenv('RUNNER_TOKEN')
    if not token_env:
        print('access denied', file=sys.stderr)
        sys.exit(1)
    token_file = open('token.txt', 'r')
    try:
        token_file_content = token_file.read().strip()
    finally:
        token_file.close()
    if token_env.strip() != token_file_content:
        print('access denied', file=sys.stderr)
        sys.exit(1)

class CommandExecutor:
    def __init__(self):
        self.active_commands = 0
        self.command_queue = Queue()
        self.lock = Lock()
        self.last_activity = time.time()
        self.command_rate_limit = 10
        self.command_concurrency_limit = 3
        self.worker_threads = []

    def add_command(self, command):
        with self.lock:
            if self.active_commands >= self.command_concurrency_limit:
                return False
            self.command_queue.put(command)
            return True

    def process_commands(self):
        while True:
            with self.lock:
                if self.command_queue.empty() and self.active_commands == 0:
                    break
                if time.time() - self.last_activity > 1:
                    self.last_activity = time.time()
                    if self.active_commands < self.command_rate_limit:
                        self.active_commands += 1
                        self.command_queue.put(None)
                else:
                    if self.active_commands < self.command_rate_limit:
                        self.active_commands += 1
                        self.command_queue.put(None)

            if not self.command_queue.empty():
                cmd = self.command_queue.get()
                if cmd is None:
                    continue
                self.active_commands -= 1
                self.last_activity = time.time()
                try:
                    process = Thread(target=self.execute_command, args=(cmd,))
                    process.start()
                    self.worker_threads.append(process)
                except Exception as e:
                    print(f'Error executing command: {e}', file=sys.stderr)

    def execute_command(self, command):
        try:
            result = os.popen(command).read()
            sys.stdout.write(result)
        except Exception as e:
            print(f'Error executing command: {e}', file=sys.stderr)

    def cleanup(self):
        for thread in self.worker_threads:
            thread.join()
        self.worker_threads = []

def main():
    verify_auth()
    executor = CommandExecutor()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if not executor.add_command(line):
            continue
    executor.process_commands()
    executor.cleanup()

if __name__ == '__main__':
    main()

import os
import sys
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from collections import deque

def verify_auth():
    required_token = os.getenv('RUNNER_TOKEN')
    if not required_token:
        print('access denied', file=sys.stderr)
        sys.exit(1)

    with open('token.txt', 'r') as f:
        provided_token = f.read().strip()

    if required_token.strip() != provided_token:
        print('access denied', file=sys.stderr)
        sys.exit(1)

def execute_command(cmd):
    try:
        result = os.popen(cmd).read()
        return result.strip()
    except Exception as e:
        return f"Command failed: {str(e)}"

def main():
    verify_auth()

    command_queue = deque()
    active_commands = 0
    last_start_time = time.time()
    command_rate_limit = 10

    with ThreadPoolExecutor(max_workers=3) as executor:
        while True:
            line = sys.stdin.readline()
            if not line:
                break
            line = line.strip()
            if not line:
                continue

            command_queue.append(line)

            # Enforce rate limit
            current_time = time.time()
            time_since_last = current_time - last_start_time
            if time_since_last < 1:
                time.sleep(1 - time_since_last)
                last_start_time = current_time
            if len(command_queue) > command_rate_limit:
                print('access denied', file=sys.stderr)
                sys.exit(1)

            # Execute commands
            while active_commands < 3 and command_queue:
                cmd = command_queue.popleft()
                future = executor.submit(execute_command, cmd)
                active_commands += 1

            for future in as_completed(executor):
                active_commands -= 1
                try:
                    result = future.result()
                    print(result, end='\n')
                except Exception as e:
                    print(f"Error executing command: {str(e)}", file=sys.stderr)

if __name__ == "__main__":
    main()
